def mappick_sql(self, expression: exp.MapPick) -> str:
    keys = expression.expressions
    x_dot_key = exp.Dot(this=exp.to_identifier("x"), expression=exp.to_identifier("key"))

    if len(keys) == 1:
        predicate = exp.ArrayContains(this=keys[0], expression=x_dot_key)
    else:
        predicate = exp.In(this=x_dot_key, expressions=keys)

    result = exp.func(
        "MAP_FROM_ENTRIES",
        exp.ArrayFilter(
            this=exp.func("MAP_ENTRIES", expression.this),
            expression=exp.Lambda(this=predicate, expressions=[exp.to_identifier("x")]),
        ),
    )
    return self.sql(result)

